L["Clear the box to go back to the page."] = "Videz le champ pour revenir à la page."
L["Hover any setting to see what it does."] = "Survolez un paramètre pour voir ce qu’il fait."
L["Preview"] = "Aperçu"
L["Unlock anchors"] = "Déverrouiller les ancres"
L["Lock anchors"] = "Verrouiller les ancres"
L["Stop preview"] = "Arrêter l’aperçu"
L["%s is off."] = "%s est désactivé."
L["%s's settings are now on %s."] = "Les paramètres de %s sont maintenant sur %s."
