L["All other feeds"] = "Tous les autres affichages"
L["Position too"] = "Position aussi"
L["Mirror left to right"] = "Miroir gauche-droite"
L["Garu Combat Text"] = "Garu Combat Text"
L["Search settings"] = "Rechercher un paramètre"
L["Copy to\226\128\166"] = "Copier vers…"
L["Puts this feed's layout and text settings onto another feed, or onto all of them. What each feed counts (thresholds, pets, mana) is left alone."] = "Applique la disposition et les réglages de texte de cet affichage à un autre, ou à tous. Ce que compte chaque affichage (seuils, familiers, mana) reste inchangé."
L["Position too moves the other feed to this one's spot; with Mirror left to right it goes to the opposite side instead, so the two sit as a pair."] = "« Position aussi » déplace l’autre affichage à cet endroit ; avec « Miroir gauche-droite », il va plutôt du côté opposé, pour que les deux forment une paire."
L["No setting by that name."] = "Aucun paramètre de ce nom."
L["Turn on"] = "Activer"
L["Selected: press Ctrl+C to copy it."] = "Sélectionné : appuyez sur Ctrl+C pour copier."
L["Imported: every setting and position is in place."] = "Importé : chaque paramètre et chaque position sont en place."
L["Every setting, anchor and position, as one string. Copy it with Ctrl+C, and import it on another character or install."] = "Chaque paramètre, ancre et position en une seule chaîne. Copiez-la avec Ctrl+C et importez-la sur un autre personnage ou une autre installation."
L["Select all"] = "Tout sélectionner"
L["Paste a profile string from Export (Ctrl+V), then Import. It replaces every setting, anchor and position at once."] = "Collez une chaîne de profil venant d’Exporter (Ctrl+V), puis Importer. Elle remplace d’un coup chaque paramètre, ancre et position."
